@router.get('/card')
async def get_card():
    """获取本 Agent 名片。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    # 尝试从文件加载
    card = app.agent_card.load() if hasattr(app.agent_card, 'load') else {}
    if not card:
        app.agent_card.build(app.skills, app.tools)
        card = app.agent_card.load() if hasattr(app.agent_card, 'load') else {}
    return card


@router.put('/card')
async def update_card(req: AgentCardUpdate):
    """更新本 Agent 名片。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    app.agent_card.build(app.skills, app.tools)
    return {'success': True, 'message': '名片已重建'}


@router.get('/peers')
async def discover_peers():
    """发现其他 Agent。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return []
    if hasattr(app.registry, 'discover'):
        return app.registry.discover()
    return []


@router.post('/invoke')
async def invoke_agent(req: A2AInvokeRequest):
    """调用其他 Agent。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    try:
        result = app.a2a_caller.invoke_chat(req.target, req.message)
        return {'success': True, 'result': result}
    except Exception as e:
        return {'success': False, 'error': str(e)}


@router.post('/register')
async def register_card():
    """向平台注册本 Agent 名片。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}
    app.agent_card.build(app.skills, app.tools)
    card = app.agent_card.load() if hasattr(app.agent_card, 'load') else {}
    result = app.registry.register(card)
    return {'success': result, 'message': '已注册' if result else '注册失败（平台不可达）'}
